  instance('Airport office roof',box,roofMaterial,-86,8.55,-84,45,.3,19);
  instance('Terminal forecourt',box,pavement,-86,-.02,-70,47,.1,8);
  for(let n=0;n<8;n++)instance('Terminal canopy posts',box,curb,-106+n*5.7,1.8,-72,.2,3.6,.2);
