function pjdCleanAircraft(root) {
  const remove = [], oldMaterials = new Set(), finishes = new Map();
  const counts = {paint:0,glass:0,metal:0,trim:0,smoothed:0};
  const physical = (name, options) => {
    if (!finishes.has(name)) {
      const material = new nt({side:ht, ...options});
      material.name = 'PJD ' + name;
      material.envMapIntensity = 1;
      finishes.set(name, material);
    }
    return finishes.get(name);
  };
  const paint = physical('porcelain aircraft enamel', {color:0xf5f4f0,metalness:0,roughness:.21,clearcoat:1,clearcoatRoughness:.085});
  const glass = physical('smoked optical glazing', {color:0x10232c,metalness:0,roughness:.075,clearcoat:1,clearcoatRoughness:.035,ior:1.52});
  const chrome = physical('polished aluminium', {color:0xd7dce0,metalness:.94,roughness:.17});
  const satin = physical('satin titanium', {color:0x858e92,metalness:.86,roughness:.32});
  const rubber = physical('tyre rubber', {color:0x161a1c,metalness:0,roughness:.85});
  const seal = physical('glazing seal', {color:0x35444a,metalness:.24,roughness:.39});
  const seam = physical('flush panel joint', {color:0x8b9394,metalness:.2,roughness:.46});
  const intake = physical('engine interior', {color:0x11181d,metalness:.25,roughness:.54});
  root.traverse(mesh => {
    if (!mesh.isMesh) return;
    const name=mesh.name;
    if (/anti[- ]collision beacon/i.test(name)) {remove.push(mesh);return;}
    mesh.receiveShadow=false;
    const old=mesh.material;
    if (Array.isArray(old) || !old?.isMeshStandardMaterial) return;
    oldMaterials.add(old);
    if (old.transparent) {
      old.depthWrite=false;old.polygonOffset=true;old.polygonOffsetFactor=-2;old.polygonOffsetUnits=-2;
      if(old.map)old.map.anisotropy=8;
      return;
    }
    // Classify per part, not per shared source material: fan blades, window
    // seals and undercarriage must not inherit the same mirror-like finish.
    if (/Cabin (window|glazing)|windscreen|Pilot side glazing|flight deck pane/i.test(name)) {
      mesh.material=glass;counts.glass++;
    } else if (/surround|window trim|glazing frame/i.test(name)) {
      mesh.material=seal;counts.trim++;
    } else if (/seam|perimeter|separation/i.test(name)) {
      mesh.material=seam;
    } else if (/tyre|tread|hydraulic hose/i.test(name)) {
      mesh.material=rubber;
    } else if (/fan blade|exhaust.*rim|exhaust nozzle|wheel hub/i.test(name)) {
      mesh.material=satin;counts.metal++;
    } else if (/inlet|exhaust centrebody|engine recess/i.test(name) && !/lip/i.test(name)) {
      mesh.material=intake;
    } else if (/intake lip|oleo|propeller spinner|gear.*brace|door handle/i.test(name)) {
      mesh.material=chrome;counts.metal++;
    } else if (old.isMeshPhysicalMaterial && old.clearcoat>.5 && old.metalness<.65) {
      if (old.color.r>.6 && old.color.g>.6 && old.color.b>.6) mesh.material=paint;
      else {
        mesh.material=physical('livery '+old.color.getHexString(),{color:old.color,metalness:.05,roughness:.24,clearcoat:1,clearcoatRoughness:.1});
      }
      counts.paint++;
    } else if (old.metalness>.65) {mesh.material=satin;counts.metal++;}
    const material=mesh.material;
    material.flatShading=false;
    material.onBeforeCompile=()=>{};
    material.customProgramCacheKey=()=> 'pjd-aircraft-finish-v6';
    material.bumpMap=null;material.normalMap=null;material.roughnessMap=null;
    delete material.userData.pjdSurface;
    material.needsUpdate=true;
    // Fine, flush joins retain detail without thick chrome outlines at card size.
    if (/surround|window trim|seam|perimeter|separation/i.test(name) && mesh.geometry.type==='TubeGeometry') {
      const p=mesh.geometry.parameters, previous=mesh.geometry;
      mesh.geometry=new Zn(p.path,p.tubularSegments,p.radius*.58,p.radialSegments,p.closed);
      previous.dispose();
    }
    // Close the shading seam at the duplicated UV boundary of lofted bodies.
    if (/fuselage/i.test(name) && !/stripe|lettering/i.test(name)) {
      const geometry=mesh.geometry, positions=geometry.attributes.position, normals=geometry.attributes.normal;
      if (positions && normals) {
        const bins=new Map();
        for(let i=0;i<positions.count;i++){
          const key=[positions.getX(i),positions.getY(i),positions.getZ(i)].map(x=>Math.round(x*1e5)).join(',');
          if(!bins.has(key))bins.set(key,[]);bins.get(key).push(i);
        }
        for(const indices of bins.values())if(indices.length>1){
          const n=new S();for(const i of indices)n.add(new S(normals.getX(i),normals.getY(i),normals.getZ(i)));
          n.normalize();for(const i of indices)normals.setXYZ(i,n.x,n.y,n.z);
        }
        normals.needsUpdate=true;counts.smoothed++;
      }
    }
  });
  for(const mesh of remove){oldMaterials.add(mesh.material);mesh.removeFromParent();mesh.geometry.dispose();}
  const used=new Set();root.traverse(m=>{if(m.material)used.add(m.material);});
  for(const material of oldMaterials)if(!used.has(material))material.dispose();
  for(const material of finishes.values())if(!used.has(material))material.dispose();
  root.userData.shaders={revision:'refined-aircraft-pbr-v6',...counts};
  root.userData.removedTopBeacons=remove.length;
  return root;
}




// Shared airside campus. Repeated parts are instanced, including fence posts.
function pjdAirport(){
  const root=new Rt();root.name='Airport grounds, taxiways and perimeter';
  const geometry=new Qt(1,1,1),dummy=new zt(),groups=new Map();
  const materials={
    asphalt:new xt({color:0x50585c,roughness:.96}),concrete:new xt({color:0xb9bebc,roughness:.9}),
    yellow:new xt({color:0xe6bd53,roughness:.8}),white:new xt({color:0xdaddd5,roughness:.85}),
    metal:new xt({color:0x78878a,metalness:.35,roughness:.62}),wall:new xt({color:0xa1aaa9,roughness:.82}),
    roof:new xt({color:0x5e6b71,metalness:.25,roughness:.7}),glass:new xt({color:0x3f606e,metalness:.25,roughness:.23}),
    vehicle:new xt({color:0xc4c9c5,roughness:.5}),red:new xt({color:0x954c40,roughness:.6})
  };
  function box(name,material,x,y,z,w,h,d){
    const key=material;if(!groups.has(key))groups.set(key,[]);
    groups.get(key).push({name,x,y,z,w,h,d});
  }
  function mark(x,z,w,d,material='yellow'){box('Airside marking',material,x,.047,z,w,.008,d);}
  function road(x,z,w,d){box('Service road','asphalt',x,-.018,z,w,.09,d);}
  road(0,-24,520,7);mark(0,-24,516,.13);
  for(const x of [-240,240]){
    road(x,-35,12,22);mark(x,-35,.13,22);
    for(const z of [-31.5,-31.1,-30.7,-30.3])mark(x,z,11,.1);
  }
  // Wider parking aprons connect to the existing central stand and taxiway.
  for(const side of [-1,1]){
    box('Business aviation apron','concrete',side*69,-.022,0,82,.055,40);
    box('Maintenance apron','concrete',side*142,-.022,47,62,.055,118);
    road(side*100,16,11,80);road(0,60,288,10);
    mark(side*100,16,.14,80);mark(0,60,288,.14);
    road(side*142,-24,80,7);mark(side*142,-24,80,.13);
    for(let row=0;row<3;row++){
      const x=side*(60+row*18);mark(x,0,.12,31);mark(x,13,5,.13);
      for(const edge of [-1,1])mark(x+edge*7,0,.07,24,'white');
    }
    for(let row=0;row<3;row++){
      const z=10+row*27;mark(side*143,z,40,.1);mark(side*159,z,.1,5);
    }
    // Hangars open onto the southern maintenance apron, clear of the runway.
    for(let unit=0;unit<3;unit++){
      const x=side*(106+unit*39),z=115,w=34,d=25,h=9+unit*.5;
      box('Maintenance hangar','wall',x,h/2,z,w,h,d);
      box('Hangar standing-seam roof','roof',x,h+.15,z,w+.7,.3,d+.7);
      box('Hangar sectional door','glass',x,h*.35,z-d/2-.08,w*.8,h*.7,.15);
      for(let rib=-3;rib<=3;rib++)box('Door division','metal',x+rib*4,h*.35,z-d/2-.18,.06,h*.7,.05);
      box('Hangar clerestory','glass',x,h*.85,z-d/2-.08,w*.86,.8,.1);
    }
    // Emergency and ground-service facilities sit outside the movement area.
    box('Ground services building','wall',side*248,3.3,82,42,6.6,27);
    box('Services roof','roof',side*248,6.8,82,43,.35,28);
    for(let bay=0;bay<4;bay++)box('Service bay','glass',side*248-14+bay*9,2.25,68.4,7,4.5,.15);
    road(side*248,54,55,25);
    for(let van=0;van<4;van++){
      const x=side*248-15+van*10;
      box('Ground vehicle',van===0?'red':'vehicle',x,.75,53,4.8,1.5,2);
      box('Vehicle windscreen','glass',x-1.3,1.6,53,1.3,.65,1.9);
    }
    for(const z of [-14,83]){
      box('Apron light mast','metal',side*176,6,z,.17,12,.17);
      box('Apron lamp bank','white',side*176,12,z,2.4,.3,.7);
    }
  }
  // Airport access and terminal parking, behind the existing terminal.
  road(-86,-127,72,25);road(0,-148,604,7);
  for(let row=0;row<2;row++)for(let stall=0;stall<14;stall++){
    const x=-119+stall*5,z=-120-row*12;mark(x,z,.07,5,'white');
    if(stall%4!==1){box('Terminal parked car','vehicle',x+2,.56,z,2.1,1.1,4.2);box('Car glazing','glass',x+2,1.21,z,1.8,.35,2.1);}
  }
  // Continuous boundary and maintenance route enclose the whole airfield.
  road(0,144,608,6);road(-304,-10,6,308);road(304,-10,6,308);
  const fenceY=1.2;
  for(let x=-318;x<=318;x+=6)for(const z of [-178,158]){
    if(z===158&&Math.abs(Math.abs(x)-78)<8)continue;
    box('Perimeter fence post','metal',x,fenceY,z,.08,2.4,.08);
  }
  for(let z=-178;z<=158;z+=6)for(const x of [-318,318])box('Perimeter fence post','metal',x,fenceY,z,.08,2.4,.08);
  for(const y of [.35,1.2,2.25]){
    box('North fence rail','metal',0,y,-178,636,.035,.035);
    for(const [x,w] of [[-204,228],[0,140],[204,228]])box('South fence rail','metal',x,y,158,w,.035,.035);
    for(const x of [-318,318])box('Side fence rail','metal',x,y,-10,.035,.035,336);
  }
  for(const x of [-80,80]){
    road(x,182,10,76);
    box('Access barrier','white',x,1.1,158,10,.12,.12);
    box('Security booth','wall',x+8,1.6,161,4,3.2,5);
    box('Security glazing','glass',x+8,2,158.45,3,.8,.08);
  }
  for(let x=-260;x<=260;x+=24)for(const z of [-30,-61])box('Taxiway marker','yellow',x,.18,z,.25,.36,.25);
  for(const [key,items]of groups){
    const mesh=new $n(geometry,materials[key],items.length);mesh.name='Airport '+key;
    items.forEach((o,i)=>{dummy.position.set(o.x,o.y,o.z);dummy.scale.set(o.w,o.h,o.d);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);});
    mesh.instanceMatrix.needsUpdate=true;mesh.castShadow=false;mesh.receiveShadow=false;mesh.computeBoundingSphere();root.add(mesh);
  }
  root.userData={boundary:{minX:-318,maxX:318,minZ:-178,maxZ:158},hangars:6,drawGroups:groups.size};
  return root;
}

